INSERT INTO membrane_retrofits (assessment_id,review_id,site_id,scope_key,option_key,revision,objective,proposed_route,feasibility,hard_constraints,evidence_basis,assumptions,missing_inputs,validation_plan,alternatives,feed_risk,pretreatment_risk,concentrate_risk,integration_risk,operational_risk,compliance_economics_risk,score_basis,updated_on) VALUES ('RA010-01','MR010-01','CN0015','high-salt','screening',1,'既有设计/历史膜系统优化初筛','优化既有UF/DTRO：查两线离子及实际回收率后试验软化、通量及CIP优化；不直接提回收率','conditional','未经确认的浓水去向不得作为可行前提；先核实实际设施与许可','INFERRED；依据 D010-01 / W01B2S02','仅在工艺仍有效且有回用或减量目标时评估','现有蒸发容量和盐销路、膜寿命、能耗待核','取得许可、验收、实际流量及多时段水质；小试预处理和膜截留/通量/CIP；做产浓水、盐泥物料衡算、全生命周期成本及合规审查','保留原回收率；源头分质',NULL,NULL,NULL,NULL,NULL,NULL,'六维均缺实际厂区参数，留NULL；不是低难度','2026-11-27');
