INSERT INTO membrane_retrofits (assessment_id,review_id,site_id,scope_key,option_key,revision,objective,proposed_route,feasibility,hard_constraints,evidence_basis,assumptions,missing_inputs,validation_plan,alternatives,feed_risk,pretreatment_risk,concentrate_risk,integration_risk,operational_risk,compliance_economics_risk,score_basis,updated_on) VALUES ('RA010-02','MR010-02','CN0063','new-scr-cleaning','screening',1,'潜在回用/减排初筛','先测沉淀出水SS、盐度与清洗水回用目标；必要时增加UF，仅在脱盐有收益且浓水闭合时考虑RO','conditional','未经确认的浓水去向不得作为可行前提；先核实实际设施与许可','INFERRED；依据 D010-02 / W01B2S22','仅在工艺仍有效且有回用或减量目标时评估','纳管许可和回用途径；实际水量、电耗及浓水去向未知','取得许可、验收、实际流量及多时段水质；小试预处理和膜截留/通量/CIP；做产浓水、盐泥物料衡算、全生命周期成本及合规审查','维持三级沉淀纳管；改善沉淀及循环清洗',NULL,NULL,NULL,NULL,NULL,NULL,'六维均缺实际厂区参数，留NULL；不是低难度','2026-11-27');
