INSERT INTO membrane_retrofits (assessment_id,review_id,site_id,scope_key,option_key,revision,objective,proposed_route,feasibility,hard_constraints,evidence_basis,assumptions,missing_inputs,validation_plan,alternatives,feed_risk,pretreatment_risk,concentrate_risk,integration_risk,operational_risk,compliance_economics_risk,score_basis,updated_on) VALUES ('RA010-03','MR010-03','CN0063','scr-regeneration','screening',1,'既有设计/历史膜系统优化初筛','以验收历史水质为基线，复核实际MBR污泥负荷及RO回收率、三效热耗后优化；分支先核图','conditional','未经确认的浓水去向不得作为可行前提；先核实实际设施与许可','INFERRED；依据 D010-03 / W01B2S22','仅在工艺仍有效且有回用或减量目标时评估','实际分流、污泥、盐处置、连续监测和运行费用待核','取得许可、验收、实际流量及多时段水质；小试预处理和膜截留/通量/CIP；做产浓水、盐泥物料衡算、全生命周期成本及合规审查','优化反应沉淀及生化；维持原RO回收率',NULL,NULL,NULL,NULL,NULL,NULL,'六维均缺实际厂区参数，留NULL；不是低难度','2026-11-27');
