INSERT INTO membrane_retrofits (assessment_id,review_id,site_id,scope_key,option_key,revision,objective,proposed_route,feasibility,hard_constraints,evidence_basis,assumptions,missing_inputs,validation_plan,alternatives,feed_risk,pretreatment_risk,concentrate_risk,integration_risk,operational_risk,compliance_economics_risk,score_basis,updated_on) VALUES ('RA010-06','MR010-06','CN0231','combined-production','screening',1,'潜在回用/减排初筛','在二沉出水或消毒后旁路小试UF+RO回用；高浓有机液维持独立处置，先测COD、盐、硬度、芬顿残铁及接触氧化出水','conditional','未经确认的浓水去向不得作为可行前提；先核实实际设施与许可','INFERRED；依据 D010-06 / W07S07','仅在工艺仍有效且有回用或减量目标时评估','浓水去向、回用水质、实际流量、残铁和有机污染、接管许可未知','取得许可、验收、实际流量及多时段水质；小试预处理和膜截留/通量/CIP；做产浓水、盐泥物料衡算、全生命周期成本及合规审查','维持现行设计纳管；优化芬顿药耗和生化、比较无膜深度处理',NULL,NULL,NULL,NULL,NULL,NULL,'六维均缺实际厂区参数，留NULL；不是低难度','2026-11-27');
