INSERT INTO w10_assert SELECT count(*)=10 FROM process_diagrams WHERE diagram_id LIKE 'D010-%';
INSERT INTO w10_assert SELECT count(*)=10 FROM membrane_reviews WHERE review_id LIKE 'MR010-%';
INSERT INTO w10_assert SELECT count(*)=0 FROM process_diagram_evidence e JOIN process_diagrams d USING(diagram_id) JOIN wastewater w USING(water_id) WHERE d.diagram_id LIKE 'D010-%' AND (d.site_id<>w.site_id OR e.source_id<>w.source_id);
INSERT INTO w10_assert SELECT count(*)=0 FROM process_diagrams d WHERE d.diagram_id LIKE 'D010-%' AND NOT EXISTS (SELECT 1 FROM site_sources a WHERE a.site_id=d.site_id AND a.source_id=d.source_id);
INSERT INTO w10_assert SELECT count(*)=0 FROM process_diagram_evidence e JOIN process_diagrams d USING(diagram_id) WHERE d.diagram_id LIKE 'D010-%' AND NOT EXISTS (SELECT 1 FROM site_sources a WHERE a.site_id=d.site_id AND a.source_id=e.source_id);
